<?php
require __DIR__.'/config.php'; require_role('partner');
$u=user();$msg=null;
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='landing'){$sid=(int)$_POST['service_id'];$q=$db->prepare('SELECT * FROM services WHERE id=? AND active=1');$q->execute([$sid]);$s=$q->fetch();if($s){$slug=slugify($u['slug'].'-'.$s['slug']).'-'.substr(bin2hex(random_bytes(2)),0,4);$st=$db->prepare('INSERT INTO landing_pages(user_id,service_id,slug,headline,subheadline) VALUES(?,?,?,?,?)');$st->execute([$u['id'],$sid,$slug,$s['title'],$s['short_description']]);$msg='Landing creata. Ora puoi personalizzarla.';}}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='lead'){$st=$db->prepare('INSERT INTO leads(user_id,service_id,name,email,phone,message,status,source) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$u['id'],(int)$_POST['service_id'],trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['message']),'new','manual']);$msg='Lead aggiunto.';}
$services=$db->query('SELECT * FROM services WHERE active=1 ORDER BY id DESC')->fetchAll();$q=$db->prepare('SELECT lp.*,s.title,s.slug service_slug FROM landing_pages lp JOIN services s ON s.id=lp.service_id WHERE lp.user_id=? ORDER BY lp.id DESC');$q->execute([$u['id']]);$pages=$q->fetchAll();$q=$db->prepare('SELECT l.*,s.title FROM leads l JOIN services s ON s.id=l.service_id WHERE l.user_id=? ORDER BY l.id DESC');$q->execute([$u['id']]);$leads=$q->fetchAll();$q=$db->prepare('SELECT COALESCE(SUM(amount),0) total,COALESCE(SUM(commission_amount),0) commissions FROM sales WHERE user_id=? AND status IN ("paid","approved")');$q->execute([$u['id']]);$sales=$q->fetch();
layout_start('Partner Dashboard');?><div class="container"><h1>Ciao <?php echo e($u['name']);?> 👋</h1><?php if($msg)echo '<div class="card">'.e($msg).'</div>';?><div class="grid"><div class="card"><div class="muted">Landing Pages</div><div class="stat"><?php echo count($pages);?></div></div><div class="card"><div class="muted">Lead</div><div class="stat"><?php echo count($leads);?></div></div><div class="card"><div class="muted">Vendite incassate</div><div class="stat">€ <?php echo number_format((float)$sales['total'],2,',','.');?></div></div><div class="card"><div class="muted">Commissioni</div><div class="stat">€ <?php echo number_format((float)$sales['commissions'],2,',','.');?></div></div></div><div class="card"><h2>Nuova Landing Page</h2><form method="post"><input type="hidden" name="action" value="landing"><select name="service_id" required><?php foreach($services as $s):?><option value="<?php echo $s['id'];?>"><?php echo e($s['title']);?> — € <?php echo number_format($s['price'],2,',','.');?> — <?php echo e($s['commission_rate']);?>%</option><?php endforeach;?></select><button class="btn">Crea landing</button></form></div><div class="card"><h2>Le mie Landing Pages</h2><table><tr><th>Servizio</th><th>Stato</th><th>Azioni</th></tr><?php foreach($pages as $p):?><tr><td><strong><?php echo e($p['title']);?></strong></td><td><?php echo $p['published']?'<span class="pill">Pubblicata</span>':'Bozza';?></td><td><a class="btn secondary" href="landing.php?id=<?php echo $p['id'];?>">Modifica</a> <a href="p.php?u=<?php echo urlencode($u['slug']);?>&s=<?php echo urlencode($p['service_slug']);?>" target="_blank">Apri</a> <a href="sales.php?service=<?php echo $p['service_id'];?>">Sales Center</a></td></tr><?php endforeach;?></table></div><div class="card"><h2>Aggiungi lead manualmente</h2><form method="post"><input type="hidden" name="action" value="lead"><div class="grid"><div><label>Servizio</label><select name="service_id"><?php foreach($services as $s):?><option value="<?php echo $s['id'];?>"><?php echo e($s['title']);?></option><?php endforeach;?></select></div><div><label>Nome</label><input name="name" required></div><div><label>Email</label><input type="email" name="email"></div><div><label>Telefono</label><input name="phone"></div></div><label>Note</label><textarea name="message" rows="4"></textarea><button class="btn">Salva lead</button></form></div><div class="card"><h2>Lead recenti</h2><table><tr><th>Cliente</th><th>Servizio</th><th>Stato</th><th>Data</th></tr><?php foreach($leads as $l):?><tr><td><?php echo e($l['name']);?><br><?php echo e($l['email']);?></td><td><?php echo e($l['title']);?></td><td><span class="pill"><?php echo e($l['status']);?></span></td><td><?php echo e($l['created_at']);?></td></tr><?php endforeach;?></table></div></div><?php layout_end();?>
